        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(
                c.initialize.selector,
                address(1), // _sGlp (EOA, unused in paths we touch)
                address(2), // _usdc
                address(3), // _rewardRouter
                address(4), // _glpManager (its vault() call to empty address returns 0)
                address(5), // _dnGmxJuniorVault
                address(6)  // _keeper
            )
        );
        require(ok, "init failed");
    }

    function testFuzz_property(address newOwner) public {
        // the deployer (this test contract) is the owner after initialize
        bool completed;
        try c.transferOwnership(newOwner) {
            completed = true;
        } catch {
            completed = false;
        }
        // GENERAL RULE: any completed transferOwnership must leave the owner nonzero
        // (equivalently: a zero-address transfer must revert).
        // Reference: reverts for newOwner == address(0) -> rule holds for every input.
        // Mutant: accepts newOwner == address(0) -> completed with owner() == address(0) -> rule breaks.
        assertTrue(!completed || c.owner() != address(0));
    }
}

