            IRewardRouterV2(makeAddr("router")),
            IGlpManager(makeAddr("glpManager")),
            makeAddr("juniorVault"),
            makeAddr("keeper")
        );
        // glpManager.vault() call target: give it code so staticcall succeeds
        // (minimal: deploy a tiny vault returning 0 price)
        // Instead of patching initialize, use a vault helper:
        // (see MinVault below)
    }

    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(receiver != address(0));
        amount = bound(amount, 1, type(uint128).max);

        address keeper = c.keeper();

        // cycle: pause then unpause -> manager is definitively NOT paused
        vm.prank(keeper);
        c.pauseDeposit();
        vm.prank(keeper);
        c.unpauseDeposit();

        bool ok;
        try c.depositUsdc(amount, receiver) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: on an unpaused manager, any admissible depositUsdc
        // call (amount > 0, receiver != 0) completes successfully.
        assertTrue(ok, "unpaused manager must accept depositUsdc");
    }
}

